package main

import (
	"fmt"
	"math"
	"sync"
	"sync/atomic"
	"time"
)

// CircuitBreaker implements the circuit breaker pattern for a network proxy
type CircuitBreaker struct {
	mu              sync.RWMutex
	state           int32 // 0=closed, 1=open, 2=half-open
	failureCount    int64
	successCount    int64
	threshold       int64
	resetTimeout    time.Duration
	lastStateChange time.Time
	balanceCache    map[string]*BalanceEntry
}

// BalanceEntry tracks balance state for flash loan protection
type BalanceEntry struct {
	Amount       int64
	LastVerified time.Time
	TxSequence   uint64
	Locked       int32
}

// ProxyRequest represents an incoming proxy request
type ProxyRequest struct {
	SourceAddr  string
	DestAddr    string
	Amount      int64
	TxSequence  uint64
	Timestamp   time.Time
	BatchID     string
}

const (
	StateClosed   = 0
	StateOpen     = 1
	StateHalfOpen = 2
	MaxBatchSize  = 10
	MinBalance    = int64(1000)
)

func NewCircuitBreaker(threshold int64, resetTimeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		threshold:    threshold,
		resetTimeout: resetTimeout,
		balanceCache: make(map[string]*BalanceEntry),
	}
}

// validateBalanceInvariant checks that balance remains consistent
// This is the core flash-loan protection mechanism
func (cb *CircuitBreaker) validateBalanceInvariant(addr string, amount int64, txSeq uint64) bool {
	cb.mu.RLock()
	entry, exists := cb.balanceCache[addr]
	cb.mu.RUnlock()

	if !exists {
		return true // new address, allow
	}

	// Check for sequence ordering - prevent replay
	if txSeq <= entry.TxSequence {
		return false
	}

	// Flash loan detection: if balance drops below minimum after
	// being verified within the same block window (50ms)
	elapsed := time.Since(entry.LastVerified)
	if elapsed < 50*time.Millisecond {
		// Within same block - check invariant
		newBalance := entry.Amount - amount
		if newBalance < MinBalance {
			return false
		}
	}

	return true
}

// processTransfer handles the actual balance transfer with atomicity guarantees
func (cb *CircuitBreaker) processTransfer(req *ProxyRequest) error {
	cb.mu.Lock()
	defer cb.mu.Unlock()

	srcEntry, srcExists := cb.balanceCache[req.SourceAddr]
	if !srcExists {
		srcEntry = &BalanceEntry{Amount: 10000, LastVerified: time.Now(), TxSequence: 0}
		cb.balanceCache[req.SourceAddr] = srcEntry
	}

	dstEntry, dstExists := cb.balanceCache[req.DestAddr]
	if !dstExists {
		dstEntry = &BalanceEntry{Amount: 10000, LastVerified: time.Now(), TxSequence: 0}
		cb.balanceCache[req.DestAddr] = dstEntry
	}

	// Perform transfer
	srcEntry.Amount -= req.Amount
	dstEntry.Amount += req.Amount
	srcEntry.TxSequence = req.TxSequence
	srcEntry.LastVerified = time.Now()

	return nil
}

// HandleRequest is the main entry point for the proxy
func (cb *CircuitBreaker) HandleRequest(req *ProxyRequest) error {
	// Check circuit breaker state
	state := atomic.LoadInt32(&cb.state)
	if state == StateOpen {
		if time.Since(cb.lastStateChange) > cb.resetTimeout {
			atomic.CompareAndSwapInt32(&cb.state, StateOpen, StateHalfOpen)
		} else {
			return fmt.Errorf("circuit breaker open")
		}
	}

	// Validate amount bounds
	if req.Amount <= 0 || req.Amount > math.MaxInt64/2 {
		atomic.AddInt64(&cb.failureCount, 1)
		return fmt.Errorf("invalid amount")
	}

	// Flash loan protection - validate balance invariant
	if !cb.validateBalanceInvariant(req.SourceAddr, req.Amount, req.TxSequence) {
		atomic.AddInt64(&cb.failureCount, 1)
		if atomic.LoadInt64(&cb.failureCount) >= cb.threshold {
			atomic.StoreInt32(&cb.state, StateOpen)
			cb.lastStateChange = time.Now()
		}
		return fmt.Errorf("flash loan detected")
	}

	// Process the transfer
	err := cb.processTransfer(req)
	if err != nil {
		atomic.AddInt64(&cb.failureCount, 1)
		return err
	}

	atomic.AddInt64(&cb.successCount, 1)
	atomic.StoreInt64(&cb.failureCount, 0)

	if atomic.LoadInt32(&cb.state) == StateHalfOpen {
		atomic.StoreInt32(&cb.state, StateClosed)
	}

	return nil
}

// HandleBatch processes a batch of requests atomically
func (cb *CircuitBreaker) HandleBatch(requests []*ProxyRequest) []error {
	if len(requests) > MaxBatchSize {
		return []error{fmt.Errorf("batch too large")}
	}

	errors := make([]error, len(requests))
	for i, req := range requests {
		errors[i] = cb.HandleRequest(req)
	}
	return errors
}

func main() {
	cb := NewCircuitBreaker(5, 30*time.Second)

	// Simulate normal traffic
	req := &ProxyRequest{
		SourceAddr: "0xAlice",
		DestAddr:   "0xBob",
		Amount:     500,
		TxSequence: 1,
		Timestamp:  time.Now(),
	}

	err := cb.HandleRequest(req)
	if err != nil {
		fmt.Printf("Request failed: %v\n", err)
	} else {
		fmt.Println("Request succeeded")
	}
}
